import { useState, useEffect } from "react";
import { X, Save } from "lucide-react";
import "../Style/.css";

const initialState = {
  ownerName: "",
  occupierName: "",
  address: "",
  mobile: "",
  ward: "",
  zone: "",
  newPropertyNo: "",
  oldPropertyNo: "",

  usageType: "Residential",
  constructionType: "A",
  constructionYear: "",
  area: "",
  rate: "",

  taxableValue: 0,
  deduction: 0,
  finalTaxableValue: 0,
  propertyTax: 0,
  educationTax: 0,
  treeTax: 0,
  fireTax: 0,
  totalTax: 0,
};

export default function PropertyDetailsForm({ isOpen, onClose }) {
  const [formData, setFormData] = useState(initialState);

  // ------------------------------
  // AUTO TAX CALCULATION
  // ------------------------------
  useEffect(() => {
    const area = parseFloat(formData.area) || 0;
    const rate = parseFloat(formData.rate) || 0;

    const taxableValue = area * rate;
    const deduction = taxableValue * 0.10; // 10% deduction
    const finalTaxableValue = taxableValue - deduction;

    // Example tax percentages (you can change later)
    const propertyTax = finalTaxableValue * 0.12;  // 12%
    const educationTax = finalTaxableValue * 0.02; // 2%
    const treeTax = finalTaxableValue * 0.01;      // 1%
    const fireTax = finalTaxableValue * 0.01;      // 1%

    const totalTax =
      propertyTax + educationTax + treeTax + fireTax;

    setFormData((prev) => ({
      ...prev,
      taxableValue,
      deduction,
      finalTaxableValue,
      propertyTax,
      educationTax,
      treeTax,
      fireTax,
      totalTax,
    }));
  }, [formData.area, formData.rate]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleSave = () => {
    console.log("Final Property Assessment Data:", formData);

    fetch("http://localhost:5001/api/property-details", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(formData),
    })
      .then((res) => res.json())
      .then((data) => {
        alert("Property Details Saved Successfully");
        onClose();
      })
      .catch((err) => {
        console.error(err);
        alert("Failed to Save");
      });
  };

  if (!isOpen) return null;

  return (
    <div className="modal-overlay">
      <div className="modal-content">
        <div className="modal-header">
          <h3>Main Property Entry Form</h3>
          <button onClick={onClose} className="modal-close-button">
            <X size={20} />
          </button>
        </div>

        <div className="modal-body">

          {/* ============================= */}
          {/* SECTION 1: OWNER DETAILS */}
          {/* ============================= */}
          <fieldset>
            <legend>Owner Details</legend>

            <input name="ownerName" placeholder="Owner Name" onChange={handleChange} />
            <input name="occupierName" placeholder="Occupier Name" onChange={handleChange} />
            <textarea name="address" placeholder="Address" onChange={handleChange} />
            <input name="mobile" placeholder="Mobile" onChange={handleChange} />
            <input name="ward" placeholder="Ward" onChange={handleChange} />
            <input name="zone" placeholder="Zone" onChange={handleChange} />
            <input name="newPropertyNo" placeholder="New Property No" onChange={handleChange} />
            <input name="oldPropertyNo" placeholder="Old Property No" onChange={handleChange} />
          </fieldset>

          {/* ============================= */}
          {/* SECTION 2: PROPERTY STRUCTURE */}
          {/* ============================= */}
          <fieldset>
            <legend>Property Structure</legend>

            <select name="usageType" onChange={handleChange}>
              <option>Residential</option>
              <option>Commercial</option>
              <option>Industrial</option>
            </select>

            <select name="constructionType" onChange={handleChange}>
              <option value="A">A</option>
              <option value="B">B</option>
              <option value="C">C</option>
              <option value="D">D</option>
              <option value="E">E</option>
            </select>

            <input
              type="number"
              name="constructionYear"
              placeholder="Construction Year"
              onChange={handleChange}
            />

            <input
              type="number"
              name="area"
              placeholder="Area"
              onChange={handleChange}
            />

            <input
              type="number"
              name="rate"
              placeholder="Rate"
              onChange={handleChange}
            />
          </fieldset>

          {/* ============================= */}
          {/* SECTION 3: TAX AUTO CALCULATION */}
          {/* ============================= */}
          <fieldset>
            <legend>Tax Calculation (Auto)</legend>

            <p>Taxable Value: ₹ {formData.taxableValue.toFixed(2)}</p>
            <p>10% Deduction: ₹ {formData.deduction.toFixed(2)}</p>
            <p>Final Taxable Value: ₹ {formData.finalTaxableValue.toFixed(2)}</p>
            <p>Property Tax (12%): ₹ {formData.propertyTax.toFixed(2)}</p>
            <p>Education Tax (2%): ₹ {formData.educationTax.toFixed(2)}</p>
            <p>Tree Tax (1%): ₹ {formData.treeTax.toFixed(2)}</p>
            <p>Fire Tax (1%): ₹ {formData.fireTax.toFixed(2)}</p>

            <h4>Total Tax: ₹ {formData.totalTax.toFixed(2)}</h4>
          </fieldset>

        </div>

        <div className="modal-footer">
          <button onClick={onClose} className="button-secondary">
            Cancel
          </button>
          <button onClick={handleSave} className="button-primary">
            <Save size={16} /> Save
          </button>
        </div>
      </div>
    </div>
  );
}
